import Particles, { initParticlesEngine } from "@tsparticles/react";
import { useEffect, useMemo, useState } from "react";
import { loadSlim } from "@tsparticles/slim";

const ParticlesComponent = (props) => {
  const [init, setInit] = useState(false);

  // Inisialisasi Particles.js hanya sekali saat komponen dipasang
  useEffect(() => {
    initParticlesEngine(async (engine) => {
      // Memuat plugin Slim untuk Particles.js
      await loadSlim(engine);
    }).then(() => {
      setInit(true);
    });
  }, []);

  const particlesLoaded = (container) => {
    console.log(container);
  };

  // Konfigurasi Particles.js
  const options = useMemo(
    () => ({
      background: {
        color: {
          value: "#1f2937", // Warna latar belakang
        },
      },
      fpsLimit: 60, // Batas frame per detik, sesuaikan untuk performa
      interactivity: {
        events: {
          onClick: {
            enable: true,
            mode: "push",
          },
          onHover: {
            enable: true,
            mode: 'repulse',
          },
        },
        modes: {
          push: {
            distance: 200,
            duration: 0.4, // Durasi lebih singkat untuk responsif
          },
          grab: {
            distance: 150,
          },
        },
      },
      particles: {
        color: {
          value: "#FFFFFF", // Warna partikel
        },
        links: {
          color: "#FFFFFF",
          distance: 100,
          enable: true,
          opacity: 0.3,
          width: 1,
        },
        move: {
          direction: "none",
          enable: true,
          outModes: {
            default: "bounce",
          },
          random: true,
          speed: 0.5, // Kecepatan lebih rendah untuk mengurangi beban
          straight: false,
        },
        number: {
          density: {
            enable: true,
          },
          value: 100, // Jumlah partikel, disesuaikan untuk performa
        },
        opacity: {
          value: 0.7, // Opacity yang sedikit lebih rendah
        },
        shape: {
          type: "circle",
        },
        size: {
          value: { min: 1, max: 3 },
        },
      },
      detectRetina: true,
    }),
    [],
  );

  return (
    <Particles
      id={props.id}
      init={particlesLoaded}
      options={options}
      className="absolute inset-0 z-[-1] w-full h-full" // Pastikan partikel di belakang
    />
  );
};

export default ParticlesComponent;
